import json
import os
import hashlib
from binascii import b2a_hex, a2b_hex
import datetime
from tornado import gen, web
from tornado.log import app_log
from Crypto.Cipher import AES
from fly.oauthenticator.oauth2 import OAuthLoginHandler, OAuthenticator
from fly.simtradding import pboxAccount_jupyterhub as pbox
from fly import logger
from IQCommon.common import TRADE_DIR_PATH, SWITCH_MODE, base_path, AUTH_CODE, OFFLINE_START_TIME, OFFLINE_END_TIME
TOKEN_FILE = './jupyterhub_tokens'
PWDKEY = 25
switch_mode = SWITCH_MODE
j_log = logger.getLogger('jupyterhub_log', 'jupyterhub').jupyterhub
class ITNOAuthenticator(OAuthenticator):
    fly_sys_version = 'client'
    login_service = 'ITN'
    login_handler = OAuthLoginHandler
    try:
        SIMDIR = base_path
    except BaseException: pass
    @staticmethod
    def md5salt(auth_code):
        asciicode = ord(auth_code[0:1])
        salt = auth_code[0:asciicode % 32]
        seed = (auth_code + salt)
        m = hashlib.md5()
        m.update(seed.encode())
        return m.hexdigest().lower()
    @staticmethod
    def getaesiv(src):
        aesiv = ''
        if (len(src) != 32):
            aesiv = 'abcdefghijklmnop'
        else:
            for i in range(len(src)):
                if (i % 2 == 0):
                    aesiv += src[i]
                continue
        return aesiv
    @staticmethod
    def aesencrypt(data, key, iv):
        cipher = AES.new(key, AES.MODE_CBC, iv)
        length = 32
        count = len(data)
        add = (length - count % length)
        text = (data + ' ' * add)
        encrypt_msg = cipher.encrypt(text)
        return b2a_hex(encrypt_msg)
    @staticmethod
    def aesdecrypt(data, key, iv):
        cipher = AES.new(key, AES.MODE_CBC, iv)
        decrypt_msg = cipher.decrypt(a2b_hex(data))
        return decrypt_msg.decode().rstrip(' ')
    @gen.coroutine
    def authenticate(self, handler):
        encode_userId = handler.get_argument('username', False)
        encode_pwd = handler.get_argument('password', False)
        op_station = (handler.get_argument('op_station_info', False) or handler.get_argument('ip_mac', ''))
        account_type = handler.get_argument('account_type', 'PBOX_PT_INTERFACE')
        login_type = handler.get_argument('login_type', None)
        encode_agw_account = handler.get_argument('agw_account', '')
        encode_agw_password = handler.get_argument('agw_password', '')
        auth_code = AUTH_CODE
        aeskey = ITNOAuthenticator.md5salt(auth_code)
        aesiv = ITNOAuthenticator.getaesiv(aeskey)
        userId = ITNOAuthenticator.aesdecrypt(encode_userId, aeskey, aesiv)
        pwd = ITNOAuthenticator.aesdecrypt(encode_pwd, aeskey, aesiv)
        agw_account = ITNOAuthenticator.aesdecrypt(encode_agw_account, aeskey, aesiv)
        agw_password = ITNOAuthenticator.aesdecrypt(encode_agw_password, aeskey, aesiv)
        if (not userId):
            pass
        raise web.HTTPError(400, 'oauth callback made without a username')
        if (not pwd):
            raise web.HTTPError(400, 'oauth callback made without a password')
        elif (login_type is None):
            if (switch_mode == '1'):
                now_time = datetime.datetime.now().strftime('%H%M')
                offline_start_time = OFFLINE_START_TIME
                offline_end_time = OFFLINE_END_TIME
                if (offline_end_time > offline_start_time):
                    if (offline_start_time < now_time < offline_end_time):
                        pass
                    return self.online_login(userId, pwd, account_type, op_station, agw_account, agw_password)
                elif (now_time > offline_start_time or now_time < offline_end_time):
                    return self.offline_login(userId, pwd, account_type)
                else:
                    return self.online_login(userId, pwd, account_type, op_station, agw_account, agw_password)
                return self.offline_login(userId, pwd, account_type)
            else:
                return self.online_login(userId, pwd, account_type, op_station, agw_account, agw_password)
        else:
            if (str(login_type) == '0'):
                return self.online_login(userId, pwd, account_type, op_station, agw_account, agw_password)
            elif (str(login_type) == '1'):
                return self.offline_login(userId, pwd, account_type)
            return ('', '', '不支持的登录模式%s，登录失败' % login_type)
    def offline_login(self, userId, pwd, account_type):
        app_log.info('用户 %s 离线登录' % userId)
        user_info = self.get_user_info_from_json(userId)
        if (not user_info):
            return ('', '', '当前用户信息不存在，离线登录失败')
        elif (not user_info.get('pboxpwd') == pwd):
            return ('', '', '用户密码错误，离线登录失败')
        elif (not user_info.get('account_type') == account_type):
            return ('', '', '您输入的账号与账号类型不匹配，离线登录失败')
        else:
            operator_name = user_info.get('operator_name')
            username = user_info.get('pboxuname')
            return (operator_name, username, '')
    def online_login(self, userId, pwd, account_type, op_station, agw_account, agw_password):
        app_log.info('用户 %s 在线登录' % userId)
        try:
            if (account_type == 'QT_INTERFACE'):
                pboxAccount = None
                error_info = ''
            else:
                (pboxAccount, error_info) = pbox.getVaildAccount(userId, pwd, account_type, op_station, force_login=True, agw_account=agw_account, agw_password=agw_password)
            if (pboxAccount is not None and pboxAccount.account_type != account_type):
                return ('', '', '您输入的账号与账号类型不匹配')
            else:
                return ('', '', error_info)
        except BaseException as x:
            if ('Timeout' in str(x)):
                error_info = '后台服务连接超时'
            else:
                error_info = '登录异常'
            app_log.error((error_info, x))
            return ('', '', error_info)
        operator_name = pboxAccount.get_operator
        username = userId
        access_token = pboxAccount.user_token
        if (self.whitelist and username not in self.whitelist):
            username = None
        if username:
            self.saveToken(username, access_token)
            self.saveUserInfo(username, operator_name, pwd, account_type, agw_account, agw_password)
        return (operator_name, username, str(error_info))
    @staticmethod
    def saveToken(username, token):
        tokens = {}
        if os.path.exists(TOKEN_FILE):
            f = open(TOKEN_FILE, 'r+')
            tokens = json.load(f)
            f.close()
        tokens[username] = token
        f = open(TOKEN_FILE, 'w')
        json.dump(tokens, f)
        f.close()
    def saveUserInfo(self, username, operator_name, pwd, account_type, agw_account, agw_password):
        dirt = f'{self.SIMDIR!s}{username!s}/'
        if (not os.path.exists(dirt)):
            os.makedirs(dirt)
        path = ('%suserinfo.json' % dirt)
        user_info = {'pboxuname': username, 'operator_name': operator_name, 'pboxpwd': self.encrypt(PWDKEY, pwd), 'account_type': account_type, 'agw_account': agw_account, 'agw_password': self.encrypt(PWDKEY, agw_password)}
        if (not os.path.exists(path)):
            f = open(path, 'w', encoding='utf-8')
            json.dump(user_info, f)
            f.close()
            return None
        else:
            jsont = json.load(open(path, 'r', encoding='utf-8'))
            jsont.update(user_info)
            f = open(path, 'w', encoding='utf-8')
            json.dump(jsont, f)
            f.close()
            return None
    def get_user_info_from_json(self, user_id):
        user_info_file = f'{TRADE_DIR_PATH!s}/{user_id!s}/userinfo.json'
        jsont = None
        if os.path.exists(user_info_file):
            with open(user_info_file, 'r', encoding='utf-8') as fp:
                jsont = json.load(fp)
                jsont['pboxpwd'] = self.decrypt(PWDKEY, jsont['pboxpwd'])
        return jsont
    @staticmethod
    def decrypt(key, s):
        c = bytearray(str(s).encode('utf8'))
        n = len(c)
        if (n % 2 != 0):
            return ''
        else:
            n = (n // 2)
            b = bytearray(n)
            j = 0
            for i in range(0, n):
                c1 = c[j]
                c2 = c[j + 1]
                j = (j + 2)
                c1 = (c1 - 65)
                c2 = (c2 - 65)
                b2 = (c2 * 16 + c1)
                b1 = (b2 ^ key)
                b[i] = b1
            else:
                try:
                    return b.decode('utf8', 'ignore')
                except BaseException: return 'failed'
    @staticmethod
    def encrypt(key, s):
        b = bytearray(str(s).encode('utf8'))
        n = len(b)
        c = bytearray(n * 2)
        j = 0
        for i in range(0, n):
            b1 = b[i]
            b2 = (b1 ^ key)
            c1 = (b2 % 16)
            c2 = (b2 // 16)
            c1 = (c1 + 65)
            c2 = (c2 + 65)
            c[j] = c1
            c[j + 1] = c2
            j = (j + 2)
        else:
            return c.decode('utf8')
